524	+   - Mô tơ: hai dao động (tam giác + sin ở quãng tám trên) qua lọc thông thấp, tần số và âm lượng theo |v|. Còi: hai nốt vuông cùng bật / tắt.
525	+   - update chỉ ghi tham số tối đa mỗi CONFIG.drive.sound.updateMs (mỗi lần là một sự kiện tự động hoá, D-018). stop() dừng và ngắt mọi nút. */
526	+import { CONFIG } from '../../config';
527	+import { audio } from '../../audio';
528	+
529	+interface DrSnd { ctx: AudioContext; o1: OscillatorNode; o2: OscillatorNode; lp: BiquadFilterNode; g: GainNode; hg: GainNode; h: OscillatorNode[] }
530	+let snd: DrSnd | null = null;
531	+let want = false, hornOn = false, lastAt = -1e9;
532	+
533	+/* Dựng chuỗi nút nếu âm thanh trang đã sẵn sàng; trả có dựng được không */
534	+function drSndBuild(): boolean {
535	+  const port = audio.sfxPort();
536	+  if (!port) return false;
537	+  const S = CONFIG.drive.sound, { ctx, out } = port;
538	+  const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = S.lowpass;
539	+  const g = ctx.createGain(); g.gain.value = 0;
540	+  const o1 = ctx.createOscillator(); o1.type = 'triangle'; o1.frequency.value = S.base;
541	+  const o2 = ctx.createOscillator(); o2.type = 'sine'; o2.frequency.value = S.base * 2;
542	+  const mix = ctx.createGain(); mix.gain.value = 0.5;
543	+  o1.connect(lp); o2.connect(mix).connect(lp); lp.connect(g).connect(out);
544	+  const hg = ctx.createGain(); hg.gain.value = hornOn ? S.hornGain : 0;
545	+  const h = S.hornHz.map((f) => { const o = ctx.createOscillator(); o.type = 'square'; o.frequency.value = f; o.connect(hg); o.start(); return o; });
546	+  hg.connect(out);
547	+  o1.start(); o2.start();
548	+  snd = { ctx, o1, o2, lp, g, hg, h };
549	+  return true;
550	+}
