564	+    snd!.o2.frequency.setTargetAtTime((S.base + S.perMs * a) * 2, t, S.smooth);
565	+    snd!.g.gain.setTargetAtTime(S.gainIdle + (S.gainMax - S.gainIdle) * k, t, S.smooth);
566	+  },
567	+  /* Còi (giữ phím H): đổi trạng thái mới ghi tham số */
568	+  horn(on: boolean): void {
569	+    if (on === hornOn) return;
570	+    hornOn = on;
571	+    if (snd) snd.hg.gain.setTargetAtTime(on ? CONFIG.drive.sound.hornGain : 0, snd.ctx.currentTime, 0.02);
572	+  },
573	+  /* Rời chế độ: dừng các dao động và ngắt nút */
574	+  stop(): void {
