588	+/* ============================ Lái xe: điều khiển cảm ứng ============================
589	+   Bốn con trỏ độc lập trên #drHud: cần gạt ngang #drSteer (ngón trái), nút GA #drGas và PHANH #drBrake (ngón phải), vuốt #drLook (vùng trống) xoay camera.
590	+   - Mỗi vùng chỉ theo con trỏ đã chạm vào nó (pointerId riêng + setPointerCapture), nên giữ cần gạt, đạp GA và vuốt camera cùng lúc không lẫn nhau;
591	+     ngón trượt ra ngoài vùng vẫn giữ cho tới khi nhấc.
592	+   - Cần gạt chỉ ngang: lấy thành phần x, bỏ thành phần dọc. Đầu ra theo quy ước của lái xe: ngón sang trái = steer > 0 (rẽ trái).
593	+   - Thả tay, pointercancel, lostpointercapture, blur, ẩn tab, xoay màn hình, đổi cỡ khung nhìn đáng kể: reset() (Review Focus 2).
594	+   - read(out) GỘP với đầu vào đã có (phím): lấy giá trị có độ lớn lớn hơn cho gas / brake / steer, không xóa đầu vào phím (máy lai có cả phím lẫn cảm ứng).
595	+   - Giữ yên ngón tay không phát sự kiện nên read báo activity() mỗi activityMs khi đang giữ gì đó; mỗi khung không cấp phát (D-018). */
596	+import { CONFIG } from '../../config';
597	+import type { DrInput } from './motion';
598	+
599	+export interface DrTouchHandlers { look(dxPx: number, dyPx: number): void; activity(): void }
600	+
601	+/* Độ lệch núm dx (px, phải +) trên cần gạt bán kính hành trình r → steer (−1..1, trái +): vùng chết rồi co giãn về ±1; dx < 0 (ngón sang trái) cho steer dương */
602	+export function drSteerFromDx(dx: number, r: number): number {
603	+  const k = r > 0 ? Math.max(-1, Math.min(1, dx / r)) : 0, a = Math.abs(k), D = CONFIG.drive.touch.dead;
604	+  if (a <= D) return 0;
605	+  return -Math.sign(k) * (a - D) / (1 - D);
606	+}
