608	+export function drTouchBind(root: HTMLElement, h: DrTouchHandlers): { read(out: DrInput): void; reset(): void } {
609	+  const pad = root.querySelector<HTMLElement>('#drSteer'), knob = root.querySelector<HTMLElement>('#drKnob');
610	+  const gas = root.querySelector<HTMLElement>('#drGas'), brake = root.querySelector<HTMLElement>('#drBrake'), look = root.querySelector<HTMLElement>('#drLook');
611	+  const T = CONFIG.drive.touch;
612	+  const sp = (k: string, v: number) => root.style.setProperty(k, v + 'px');   // kích thước các nút lấy từ CONFIG
613	+  sp('--dr-pad-w', T.padW); sp('--dr-pad-h', T.padH); sp('--dr-knob', T.knob);
614	+  sp('--dr-gas-w', T.gasW); sp('--dr-gas-h', T.gasH); sp('--dr-brake-w', T.brakeW); sp('--dr-brake-h', T.brakeH);
615	+  let padId = -1, cx = 0, dx = 0, r = (T.padW - T.knob) / 2;          // cần gạt: con trỏ, tâm x (px màn hình, chốt lúc chạm), độ lệch núm, hành trình núm
616	+  let padW = 0, padH = 1, lastAct = 0;                                  // cỡ khung nhìn lúc chạm cần gạt hoặc bàn đạp, lần báo "còn đó" gần nhất (ms)
617	+  let gasId = -1, brakeId = -1, lookId = -1, lx = 0, ly = 0;          // hai bàn đạp, vuốt camera (vị trí trước)
618	+  const own = (el: HTMLElement, e: PointerEvent) => { try { el.setPointerCapture(e.pointerId); } catch { /* con trỏ không còn hoạt động (sự kiện giả) */ } };
619	+  const lit = (el: HTMLElement | null, on: boolean) => { if (el) el.classList.toggle('on', on); };
620	+  const knobTo = (x: number) => { if (knob) knob.style.transform = x === 0 ? '' : `translateX(${x}px)`; };
621	+  const reset = () => { padId = -1; gasId = -1; brakeId = -1; lookId = -1; dx = 0; knobTo(0); lit(gas, false); lit(brake, false); };
622	+
623	+  if (pad) {
624	+    pad.addEventListener('pointerdown', (e) => {
625	+      if (padId >= 0) return;
626	+      e.preventDefault();
627	+      const b = pad.getBoundingClientRect();
628	+      cx = b.left + b.width / 2; r = Math.max(1, (b.width - (knob ? knob.offsetWidth || T.knob : T.knob)) / 2);
629	+      padId = e.pointerId; padW = window.innerWidth; padH = window.innerHeight; lastAct = performance.now(); own(pad, e); h.activity();
630	+      pad.dispatchEvent(new PointerEvent('pointermove', { pointerId: e.pointerId, clientX: e.clientX, clientY: e.clientY }));   // núm theo ngón ngay lúc chạm
631	+    });
632	+    pad.addEventListener('pointermove', (e) => {
633	+      if (e.pointerId !== padId) return;
634	+      dx = Math.max(-r, Math.min(r, e.clientX - cx));   // chỉ thành phần ngang; núm không ra khỏi hành trình
635	+      knobTo(dx); h.activity();
636	+    });
637	+    const padEnd = (e: PointerEvent) => { if (e.pointerId === padId) { padId = -1; dx = 0; knobTo(0); } };
638	+    pad.addEventListener('pointerup', padEnd);
639	+    pad.addEventListener('pointercancel', padEnd);
640	+    pad.addEventListener('lostpointercapture', padEnd);
641	+  }
642	+
643	+  /* Bàn đạp: giữ là 1, nhả là 0 */
644	+  const pedal = (el: HTMLElement | null, get: () => number, set: (v: number) => void) => {
645	+    if (!el) return;
646	+    el.addEventListener('pointerdown', (e) => {
647	+      if (get() >= 0) return;
648	+      e.preventDefault();
649	+      set(e.pointerId); padW = window.innerWidth; padH = window.innerHeight; lastAct = performance.now(); own(el, e); lit(el, true); h.activity();
650	+    });
651	+    const end = (e: PointerEvent) => { if (e.pointerId === get()) { set(-1); lit(el, false); } };
652	+    el.addEventListener('pointerup', end);
653	+    el.addEventListener('pointercancel', end);
654	+    el.addEventListener('lostpointercapture', end);
655	+  };
656	+  pedal(gas, () => gasId, (v) => { gasId = v; });
657	+  pedal(brake, () => brakeId, (v) => { brakeId = v; });
658	+
659	+  if (look) {
