671	+    look.addEventListener('pointerup', lookEnd);
672	+    look.addEventListener('pointercancel', lookEnd);
673	+    look.addEventListener('lostpointercapture', lookEnd);
674	+  }
675	+
676	+  root.addEventListener('contextmenu', (e) => e.preventDefault());   // giữ lâu không bật menu ngữ cảnh
