content.content:
src\styles\main.css:245:body.compact.sheet-settings .brand,body.compact.sheet-views .views{z-index:10;}   /* tờ đang mở nằm trên chú thích Tour/bão (không z-index thì chú thích đứng sau trong DOM nên đè lên) */
src\styles\main.css:285:#exHint,#exSpeed,#btnExExit,#exMpLabels,#exMpRoster,#exMpNotice{display:none;}
src\styles\main.css:288:body.explore #btnExExit{display:block;inset-inline-end:calc(14px + env(safe-area-inset-right,0px));top:calc(56px + env(safe-area-inset-top,0px));padding:8px 14px;font-size:12px;color:var(--text);cursor:pointer;}
src\styles\main.css:361:body.stroll #stHud{display:block;position:fixed;inset:0;z-index:4;pointer-events:none;touch-action:none;user-select:none;-webkit-user-select:none;-webkit-touch-callout:none;}
src\styles\main.css:362:body.ex-watching #stHud{display:none;}
src\styles\main.css:376:  body.stroll #stLook{display:block;position:fixed;pointer-events:auto;touch-action:none;right:0;width:50%;top:calc(110px + env(safe-area-inset-top,0px));bottom:0;}   /* nửa phải, dưới nút Thoát và 📷 */
src\styles\main.css:380:body.compact #btnExExit{top:calc(8px + env(safe-area-inset-top,0px));inset-inline-end:calc(8px + env(safe-area-inset-right,0px));min-height:40px;}

